import { storage } from "@/lib/storage";
import { plainText } from "@/lib/rich-text";

/**
 * Publishes a compact snapshot of upcoming reminders so the native
 * Android home-screen widget (generated by scripts/patch-native.mjs) can
 * render it. Fully offline — values live in device Preferences only.
 */

export const WIDGET_KEY = "dn_widget_reminders";

const fmt = (time?: string) => {
  if (!time) return "";
  const [h, m] = time.split(":").map(Number);
  const period = h >= 12 ? "PM" : "AM";
  return `${h % 12 === 0 ? 12 : h % 12}:${String(m).padStart(2, "0")} ${period}`;
};

export const buildWidgetSnapshot = () => {
  const now = new Date();
  const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
  const items = storage
    .getTasks()
    .filter((t) => !t.completed)
    .sort((a, b) => {
      const at = a.dueDate ? new Date(`${a.dueDate}T${a.dueTime || "00:00"}`).getTime() : Number.MAX_SAFE_INTEGER;
      const bt = b.dueDate ? new Date(`${b.dueDate}T${b.dueTime || "00:00"}`).getTime() : Number.MAX_SAFE_INTEGER;
      return at - bt;
    })
    .slice(0, 4)
    .map((t) => ({
      text: plainText(t.memo || t.title).split("\n")[0].slice(0, 60),
      when: t.dueDate ? (t.dueDate === today ? fmt(t.dueTime) || "Today" : `${t.dueDate} ${fmt(t.dueTime)}`.trim()) : t.location ? "At place" : "",
      important: !!t.important,
    }));

  return { updatedAt: Date.now(), count: items.length, items };
};

export const syncWidget = async () => {
  const snapshot = JSON.stringify(buildWidgetSnapshot());
  try {
    localStorage.setItem(WIDGET_KEY, snapshot);
    const { Capacitor } = await import("@capacitor/core");
    if (!Capacitor.isNativePlatform()) return;
    const { Preferences } = await import("@capacitor/preferences");
    await Preferences.set({ key: WIDGET_KEY, value: snapshot });
  } catch { /* widget sync is best-effort */ }
};
